// Prepare Enhanced Review Context
try {
  const mrData = $('GitLab MR Trigger').first().json.body;
  const diffData = $input.first().json;

  // Extract changed files with their diffs
  const changedFiles = (diffData.changes || []).map(change => ({
    old_path: change.old_path,
    new_path: change.new_path,
    diff: change.diff,
    new_file: change.new_file,
    deleted_file: change.deleted_file,
    renamed_file: change.renamed_file
  }));

  // Generate unique review ID
  const reviewId = `review-${mrData.project.id}-${mrData.object_attributes.iid}-${Date.now()}`;

  // Detect programming languages from file extensions
  const detectedLanguages = new Set();
  changedFiles.forEach(f => {
    const ext = f.new_path.split('.').pop();
    if (['js', 'jsx', 'ts', 'tsx'].includes(ext)) detectedLanguages.add('javascript');
    else if (['py'].includes(ext)) detectedLanguages.add('python');
    else if (['java', 'kt'].includes(ext)) detectedLanguages.add('java');
    else if (['go'].includes(ext)) detectedLanguages.add('go');
    else if (['rs'].includes(ext)) detectedLanguages.add('rust');
    else if (['php'].includes(ext)) detectedLanguages.add('php');
    else if (['rb'].includes(ext)) detectedLanguages.add('ruby');
    else if (['cs'].includes(ext)) detectedLanguages.add('csharp');
    else if (['sql'].includes(ext)) detectedLanguages.add('sql');
  });

  // Prepare enhanced context for all agents
  const reviewContext = {
    review_id: reviewId,
    mr_iid: mrData.object_attributes.iid,
    project_id: mrData.project.id,
    project_path: mrData.project.path_with_namespace,
    source_branch: mrData.object_attributes.source_branch,
    target_branch: mrData.object_attributes.target_branch,
    head_sha: mrData.object_attributes.last_commit?.id || '',
    base_sha: diffData.diff_refs?.base_sha || '',
    head_sha_full: diffData.diff_refs?.head_sha || '',
    start_sha: diffData.diff_refs?.start_sha || '',
    title: mrData.object_attributes.title,
    description: mrData.object_attributes.description || '',
    author: mrData.user?.username || 'unknown',
    changed_files: changedFiles,
    file_count: changedFiles.length,
    additions: mrData.object_attributes.additions || 0,
    deletions: mrData.object_attributes.deletions || 0,
    gitlab_url: $('Config').first().json.GITLAB_URL,
    detected_languages: Array.from(detectedLanguages),
    // Configuration from environment
    config: {
      min_severity: $('Config').first().json.MIN_SEVERITY || 'low',
      review_mode: $('Config').first().json.REVIEW_MODE || 'thorough',
      max_findings_per_agent: parseInt($('Config').first().json.MAX_FINDINGS_PER_AGENT || '20'),
      review_mode_instruction: (() => {
        const mode = $('Config').first().json.REVIEW_MODE || 'thorough';
        if (mode === 'quick') return 'Focus ONLY on critical and high severity issues. Be brief and concise.';
        if (mode === 'balanced') return 'Focus on high-impact issues. Report medium+ severity only.';
        return 'Be thorough. Report all findings at all severity levels.';
      })()
    },
    created_at: new Date().toISOString()
  };

  return [{ json: reviewContext }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'prepare_context' } }];
}

// Parse and aggregate all agent findings with enhanced analysis
try {
  const context = $('Prepare Review Context').first().json;
  const agentResults = $input.all();

  let allFindings = [];
  const agentStats = {};

  // Parse each agent's response
  for (const result of agentResults) {
    try {
      const response = result.json;
      // Skip failed agent results
      if (response.error) continue;
      // Handle OpenRouter response format
      const content = response.choices?.[0]?.message?.content || '';

      // Extract JSON from the response (handle markdown code blocks)
      let jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/);
      if (!jsonMatch) {
        // Try to find JSON in code blocks
        jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
        if (jsonMatch) {
          const innerMatch = jsonMatch[1].match(/\[\s*\{[\s\S]*\}\s*\]/);
          if (innerMatch) jsonMatch = innerMatch;
        }
      }

      if (jsonMatch) {
        const findings = JSON.parse(jsonMatch[0]);
        allFindings = allFindings.concat(findings);

        // Track agent stats
        for (const f of findings) {
          if (!agentStats[f.category]) agentStats[f.category] = 0;
          agentStats[f.category]++;
        }
      }
    } catch (e) {
      console.log('Error parsing agent response:', e.message);
    }
  }

  // Filter by minimum severity if configured
  const minSeverity = context.config.min_severity || 'low';
  const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
  const minSeverityValue = severityOrder[minSeverity] || 3;

  allFindings = allFindings.filter(f => {
    const sevValue = severityOrder[f.severity] || 3;
    return sevValue <= minSeverityValue;
  });

  // Limit findings per agent if configured
  const maxPerAgent = context.config.max_findings_per_agent || 20;
  const limitedFindings = [];
  const findingsByCategory = {};

  for (const f of allFindings) {
    if (!findingsByCategory[f.category]) findingsByCategory[f.category] = [];
    if (findingsByCategory[f.category].length < maxPerAgent) {
      findingsByCategory[f.category].push(f);
    }
  }

  for (const cat of Object.values(findingsByCategory)) {
    limitedFindings.push(...cat);
  }

  allFindings = limitedFindings;

  // Sort by severity
  allFindings.sort((a, b) => 
    (severityOrder[a.severity] || 4) - (severityOrder[b.severity] || 4)
  );

  // Add ID to each finding (1-based index)
  allFindings = allFindings.map((f, idx) => ({ ...f, id: idx + 1 }));

  // Count by severity and category
  const stats = {
    total: allFindings.length,
    critical: allFindings.filter(f => f.severity === 'critical').length,
    high: allFindings.filter(f => f.severity === 'high').length,
    medium: allFindings.filter(f => f.severity === 'medium').length,
    low: allFindings.filter(f => f.severity === 'low').length,
    by_category: agentStats
  };

  // Calculate risk score (0-100)
  const riskWeights = { critical: 25, high: 10, medium: 3, low: 1 };
  let riskScore = 0;
  for (const f of allFindings) {
    riskScore += riskWeights[f.severity] || 1;
  }
  riskScore = Math.min(100, riskScore);

  // Calculate overall confidence based on finding confidence
  const confidenceCounts = { high: 0, medium: 0, low: 0 };
  for (const f of allFindings) {
    if (f.confidence) confidenceCounts[f.confidence]++;
  }
  const totalWithConfidence = allFindings.filter(f => f.confidence).length;
  const highConfidenceRatio = totalWithConfidence > 0 ? confidenceCounts.high / totalWithConfidence : 0.5;
  const overallConfidence = Math.round(50 + (highConfidenceRatio * 40) + (confidenceCounts.medium / totalWithConfidence || 0) * 10);

  // Generate executive summary
  const executiveSummary = generateExecutiveSummary(context, allFindings, stats, riskScore, overallConfidence);

  // Format draft review comment
  const devComment = formatDeveloperComment(context, allFindings, stats, executiveSummary, riskScore, overallConfidence);
  const ctoComment = formatCTOComment(context, riskScore, overallConfidence);

  return [{
    json: {
      review_id: context.review_id,
      mr_iid: context.mr_iid,
      project_id: context.project_id,
      findings: allFindings,
      stats: stats,
      risk_score: riskScore,
      confidence_score: overallConfidence,
      executive_summary: executiveSummary,
      developer_comment: devComment,
      cto_comment: ctoComment,
      context: context
    }
  }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stack: error.stack, stage: 'format_draft' } }];
}

function generateExecutiveSummary(ctx, findings, stats, riskScore, confidence) {
  let summary = '';

  // Risk assessment
  let riskLevel = 'LOW';
  if (riskScore >= 70) riskLevel = 'CRITICAL';
  else if (riskScore >= 40) riskLevel = 'HIGH';
  else if (riskScore >= 20) riskLevel = 'MEDIUM';

  // Recommendation
  let recommendation = 'APPROVE to merge';
  if (stats.critical > 0) recommendation = 'REQUEST CHANGES - Critical issues must be fixed';
  else if (stats.high >= 3 || riskScore >= 40) recommendation = 'RECOMMENDS CHANGES - Address high-severity issues before merge';
  else if (stats.high > 0 || stats.medium >= 5) recommendation = 'REVIEW RECOMMENDED - Address findings before merge';

  // Build summary
  summary += `This MR introduces **${stats.total} finding(s)** across **${Object.keys(stats.by_category || {}).length}** categories.\n`;
  summary += `**Risk Level:** ${riskLevel} (Score: ${riskScore}/100) | **AI Confidence:** ${confidence}%\n\n`;
  summary += `**Recommendation:** ${recommendation}\n\n`;

  // Critical issues summary
  const criticalIssues = findings.filter(f => f.severity === 'critical');
  if (criticalIssues.length > 0) {
    summary += `**Must Fix (${criticalIssues.length}):** `;
    summary += criticalIssues.slice(0, 3).map(f => `${f.title} (${f.file_path}:${f.line})`).join('; ');
    if (criticalIssues.length > 3) summary += `, and ${criticalIssues.length - 3} more`;
  }

  return summary;
}

function formatDeveloperComment(ctx, findings, stats, execSummary, riskScore, confidence) {
  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  const categoryEmoji = {
    'security': '🔒',
    'performance': '⚡',
    'architecture': '🏗️',
    'code-quality': '✨',
    'test-coverage': '🧪',
    'style': '🎨',
    'context': '🔗'
  };

  // Risk level emoji and color
  let riskEmoji = '🟢';
  if (riskScore >= 70) riskEmoji = '🔴';
  else if (riskScore >= 40) riskEmoji = '🟠';
  else if (riskScore >= 20) riskEmoji = '🟡';

  let comment = `## 🤖 AI Code Review\n\n`;

  // Executive Summary Section
  comment += `### 📋 Executive Summary\n\n`;
  comment += execSummary;
  comment += `\n---\n\n`;

  // MR Info
  comment += `**MR:** !${ctx.mr_iid} - ${ctx.title}\n`;
  comment += `**Author:** @${ctx.author} | **Branch:** \`${ctx.source_branch}\` → \`${ctx.target_branch}\`\n`;
  comment += `**Files Changed:** ${ctx.file_count} (+${ctx.additions}/-${ctx.deletions})\n\n`;

  comment += `---\n\n`;

  // Stats Section with Risk Score
  comment += `### 📊 Analysis Summary\n\n`;
  comment += `| **Risk Score:** ${riskEmoji} **${riskScore}/100** | **AI Confidence:** **${confidence}%** |\n`;
  comment += `|---|---|\n`;
  comment += `| 🔴 Critical | ${stats.critical} |\n`;
  comment += `| 🟠 High | ${stats.high} |\n`;
  comment += `| 🟡 Medium | ${stats.medium} |\n`;
  comment += `| ⚪ Low | ${stats.low} |\n`;
  comment += `| **Total Findings** | **${stats.total}** |\n\n`;

  // Numbered findings table
  comment += `### 📋 Findings\n\n`;
  comment += `| # | Severity | Category | File | Line | Issue |\n`;
  comment += `|---|----------|----------|------|------|-------|\n`;

  for (const f of findings) {
    const catIcon = categoryEmoji[f.category] || '📋';
    const sevIcon = sevEmoji[f.severity] || '⚪';
    const confidenceTag = f.confidence ? ` [${f.confidence}]` : '';
    comment += `| **${f.id}** | ${sevIcon} ${f.severity}${confidenceTag} | ${catIcon} ${f.category} | \`${f.file_path}\` | ${f.line} | ${f.title} |\n`;
  }

  comment += `\n`;

  // Detailed findings by category
  comment += `<details>\n<summary>📖 Click to expand detailed findings</summary>\n\n`;

  const categories = ['security', 'performance', 'architecture', 'code-quality', 'test-coverage', 'style', 'context'];

  for (const cat of categories) {
    const catFindings = findings.filter(f => f.category === cat);
    if (catFindings.length > 0) {
      comment += `#### ${categoryEmoji[cat] || '📋'} ${cat.charAt(0).toUpperCase() + cat.slice(1).replace('-', ' ')} (${catFindings.length})\n\n`;
      for (const f of catFindings) {
        const sevIcon = sevEmoji[f.severity] || '⚪';
        comment += `**[${f.id}]** ${sevIcon} **${f.title}**\n`;
        comment += `- 📁 \`${f.file_path}:${f.line}\`\n`;
        if (f.subcategory) comment += `- 🏷️ Subcategory: \`${f.subcategory}\`\n`;
        comment += `- 📝 ${f.description}\n`;
        if (f.suggestion) {
          comment += `- 💡 *${f.suggestion}*\n`;
        }
        if (f.cwe_id) {
          comment += `- 🔗 [CWE-${f.cwe_id}](https://cwe.mitre.org/data/definitions/${f.cwe_id.replace('CWE-', '')}.html)\n`;
        }
        if (f.impact) {
          comment += `- ⚡ Impact: ${f.impact}\n`;
        }
        if (f.metrics) {
          comment += `- 📊 Metrics: ${f.metrics}\n`;
        }
        if (f.related_files && f.related_files.length > 0) {
          comment += `- 🔗 Related: ${f.related_files.map(ff => `\`${ff}\``).join(', ')}\n`;
        }
        comment += `\n`;
      }
    }
  }

  comment += `</details>\n\n`;

  comment += `---\n\n`;
  comment += `*Review ID: \`${ctx.review_id}\` | Powered by AI Code Review*\n`;

  return comment;
}

function formatCTOComment(ctx, riskScore, confidence) {
  let comment = `### 🔧 CTO Review Panel\n\n`;
  comment += `| Command | Description |\n`;
  comment += `|---------|-------------|\n`;
  comment += `| \`!approve\` | Post **all** findings as inline comments |\n`;
  comment += `| \`!approve-partial 1,3,5-7\` | Post only selected findings (by #) |\n`;
  comment += `| \`!reject\` | Discard all findings |\n`;
  comment += `| \`!remove-finding 2,4\` | Remove findings from list |\n`;
  comment += `| \`!edit-finding 1 severity:low\` | Edit a finding's severity |\n`;
  comment += `| \`!add-comment file.js:42 \"msg\"\` | Add your own inline comment |\n`;
  comment += `| \`!list-findings\` | Re-display current findings |\n`;
  comment += `| \`!explain <id>\` | Get detailed explanation of a finding |\n`;
  comment += `| \`!rerun-agent <agent>\` | Re-run specific review agent |\n\n`;
  comment += `*Model: ${$('Config').first().json.OPENROUTER_MODEL} | Review ID: \`${ctx.review_id}\`*\n`;

  return comment;
}

// Build raw SQL INSERT to avoid n8n queryParams comma-splitting bug
try {
  const fmt = $('Format Draft Comment').first().json;
  const note = $('Post Draft Comment to GitLab').first().json;
  const config = $('Config').first().json;

  function escapeSQL(val) {
    if (val === null || val === undefined) return 'NULL';
    if (typeof val === 'number') return String(val);
    return "'" + String(val).replace(/'/g, "''") + "'";
  }

  const reviewMetadata = JSON.stringify({
    risk_score: fmt.risk_score,
    executive_summary: fmt.executive_summary,
    model: config.OPENROUTER_MODEL,
    languages: fmt.context.detected_languages
  });

  const columns = [
    'review_id', 'mr_iid', 'project_id', 'findings', 'stats',
    'draft_note_id', 'confidence_score', 'review_metadata',
    'base_sha', 'head_sha', 'start_sha', 'status', 'created_at'
  ];

  const values = [
    escapeSQL(fmt.review_id),
    fmt.mr_iid,
    fmt.project_id,
    escapeSQL(JSON.stringify(fmt.findings)),
    escapeSQL(JSON.stringify(fmt.stats)),
    note.notes[0].id,
    fmt.confidence_score,
    escapeSQL(reviewMetadata),
    escapeSQL(fmt.context.base_sha),
    escapeSQL(fmt.context.head_sha_full),
    escapeSQL(fmt.context.start_sha),
    "'pending_approval'",
    'NOW()'
  ];

  const query = `INSERT INTO pending_reviews (${columns.join(', ')}) VALUES (${values.join(', ')})`;

  return [{ json: { query } }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stack: error.stack } }];
}

// Record agent execution data and build multi-row INSERT SQL
try {
  const context = $json;
  const review_id = context.review_id;
  const findings = context.findings || [];
  const completedAt = new Date().toISOString();

  function escapeSQL(val) {
    if (val === null || val === undefined) return 'NULL';
    if (typeof val === 'number') return String(val);
    return "'" + String(val).replace(/'/g, "''") + "'";
  }

  const agentCategories = ['security', 'performance', 'style', 'architecture', 'test-coverage', 'code-quality', 'context'];

  const valueRows = agentCategories.map(agent => {
    const count = findings.filter(f => f.category === agent).length;
    return `(${escapeSQL(review_id)}, ${escapeSQL(agent)}, ${count}, 'completed', ${escapeSQL(completedAt)})`;
  });

  const query = `INSERT INTO agent_runs (review_id, agent_name, findings_count, status, completed_at) VALUES ${valueRows.join(', ')}`;

  return [{ json: { query } }];
} catch (error) {
  return [{ json: { error: true, message: error.message } }];
}

// Enrich review context with learned project patterns
try {
  const context = $('Prepare Review Context').first().json;
  const patternData = $input.first().json;

  let learnedContext = 'No historical review data available for this project.';

  if (patternData && patternData.patterns && !patternData.error) {
    const patterns = typeof patternData.patterns === 'string' ? JSON.parse(patternData.patterns) : patternData.patterns;
    const parts = [];

    if (patterns.conventions) {
      parts.push(`Project conventions: ${JSON.stringify(patterns.conventions)}`);
    }
    if (patterns.common_ignore_rules && patterns.common_ignore_rules.length > 0) {
      parts.push(`Commonly ignored patterns: ${patterns.common_ignore_rules.join(', ')}`);
    }
    if (patterns.false_positives && patterns.false_positives.length > 0) {
      parts.push(`Known false positives to avoid: ${patterns.false_positives.slice(0, 10).join(', ')}`);
    }
    if (patterns.accepted_patterns && patterns.accepted_patterns.length > 0) {
      parts.push(`Previously accepted issue types: ${patterns.accepted_patterns.slice(0, 10).join(', ')}`);
    }

    if (parts.length > 0) {
      learnedContext = `Project review history (${patternData.total_reviews || 0} reviews, ${patternData.accepted_findings || 0} accepted, ${patternData.rejected_findings || 0} rejected):\n` + parts.join('\n');
    }
  }

  // Pass through context with learned data added
  return [{ json: { ...context, learned_context: learnedContext } }];
} catch (error) {
  // On error, pass context through without patterns
  const context = $('Prepare Review Context').first().json;
  return [{ json: { ...context, learned_context: 'No historical review data available for this project.' } }];
}
